    # items and stats by role
    let shards_bought = floor( gold() / 30 )
    let treasure_n = floor( shards_bought / 2 )
    let rest_after_treasure = shards_bought - treasure_n
    let jungle_n = floor( rest_after_treasure / 2 )
    let rest_after_jungle = rest_after_treasure - jungle_n
    let caster = i_am(champ_marcella()) or i_am(champ_prism()) or i_am(champ_cassi_issac()) or i_am(champ_willow())
    let tank = i_am(champ_ren()) or i_am(champ_varg())
    let main_n = floor( rest_after_jungle / 2 )
    buy( shard_of(family_treasure(), stat_strength()), treasure_n )
    buy( shard_of(family_jungle(), stat_health()), jungle_n )
    if caster:
        buy( shard(stat_focus()), main_n )
    elif tank:
        buy( shard(stat_health()), main_n )
    else:
        buy( shard(stat_strength()), main_n )
    buy( shard(stat_health()), rest_after_jungle - main_n )
    if not has_teleport() and gold() >= 40:
        buy_teleport()
    if health() < max_health() and not exists(first(filter(foes, in_attack_range()))):
        end_turn()

# retreat at 30% health when threatened; recall only when no enemy is close
if not at_spawn and health() < 0.3 * max_health():
    if (in_danger() or enemies_within(8) > 0):
        let home = closest( spawn_region(ally()) )
        if has_teleport() and distance(position(), home) <= 3:
            teleport_to(home)
            end_turn()
        if fuel_remaining() > 60000:
            dash_to(0, home)
            dash_to(1, home)
        move_towards(home)
        end_turn()
    recall()
    end_turn()
if not at_spawn and gems() > 0 and health() < 0.5 * max_health() and not (in_danger() or enemies_within(8) > 0):
    recall()
    end_turn()

# CAST-AHEAD: cast at a close enemy champion before it reaches us; the nearest enemy becomes the
# team target so allies converge on it (shared focus)
if exists( first(foes) ):
    let near_foe = nearest( foes )
    if exists(near_foe) and distance(position(), unit_position(near_foe)) <= 4 and not contains( spawn_region(enemy()), unit_position(near_foe) ):
        set_team_target(near_foe)
        if ability_ready(1) and slot_radius(1) >= 2 and slot_is_aoe(1) and not slot_is_dash(1) and not slot_is_shield(1) and not slot_is_heal(1) and not slot_is_reset(1) and distance(position(), unit_position(near_foe)) <= slot_range(1) and enemies_within(slot_radius(1)) >= 2:
            cast_at_tile(1, unit_position(near_foe))
        else:
            cast_foe(near_foe)

# HEAL ALLY: heal slots go to the weakest hurt visible ally in range (never to an enemy, never wasted on self)
if (ability_ready(0) and slot_is_heal(0)) or (ability_ready(1) and slot_is_heal(1)):
    let hurt = weakest( allies_visible() )
    if exists(hurt) and unit_health_frac(hurt) < 0.6:
        if ability_ready(0) and slot_is_heal(0) and distance(position(), unit_position(hurt)) <= slot_range(0):
            cast_at_unit(0, hurt)
        elif ability_ready(1) and slot_is_heal(1) and distance(position(), unit_position(hurt)) <= slot_range(1):
            cast_at_unit(1, hurt)

let nf = nearest( foes )

# KITE (ranged): a foe within 2 tiles gets our opener, then we step back out of reach. No attack this turn.
if exists(nf) and i_am_ranged() and can_move() and distance(position(), unit_position(nf)) <= 2 and not contains( spawn_region(enemy()), unit_position(nf) ):
    cast_foe(nf)
    move_away_from( unit_position(nf) )
    end_turn()

# FIRST HIT (melee dive): a foe 2-4 tiles away while the local fight favours us. Open with an ability,
# step in; the focus fire below then lands the attack on the same turn.
if exists(nf) and not i_am_ranged() and can_move() and distance(position(), unit_position(nf)) >= 2 and distance(position(), unit_position(nf)) <= 4 and local_strength(6) >= 1 and not contains( spawn_region(enemy()), unit_position(nf) ):
    cast_foe(nf)
    move_towards( unit_position(nf) )

# FIRST HIT (ranged close-in): a foe 4-6 tiles away and the fight favours us, so close to attack range 3
if exists(nf) and i_am_ranged() and can_move() and distance(position(), unit_position(nf)) >= 4 and distance(position(), unit_position(nf)) <= 6 and local_strength(6) >= 1 and not contains( spawn_region(enemy()), unit_position(nf) ):
    move_towards( unit_position(nf) )

# focus fire: all allies pick the weakest in-range enemy, which converges them on one target
let tgt = weakest( filter( foes, in_attack_range() ) )
if exists(tgt) and not contains( spawn_region(enemy()), unit_position(tgt) ):
    cast_on(0, tgt)
    cast_on(1, tgt)
    attack(tgt)
    if ability_ready(0) and slot_is_reset(0):
        cast_self(0)
    if ability_ready(1) and slot_is_reset(1):
        cast_self(1)
    attack(tgt)
    end_turn()

# outnumbered: an enemy is close but the local fight favours them, so step away instead of walking in
if exists(nf) and distance(position(), unit_position(nf)) <= 5 and local_strength(6) < 0.8 and not contains( spawn_region(enemy()), unit_position(nf) ):
    move_away_from( unit_position(nf) )
    end_turn()

# tribute only with a worthwhile bag (or when hurt / late game)
let bag_ready = gems() >= 25 or round_number() > 1500 or health() < 0.3 * max_health()
if gems() > 0 and bag_ready:
    let altar = first( filter( altars(), within(1, position()) ) )
    if exists(altar):
        tribute(altar)
        end_turn()
    let target = closest( minus( safe_altar_ring, ring(locked_altars(), 1) ) )
    if exists(target):
        move_towards(target)
        end_turn()
    let target2 = closest(safe_altar_ring)
    if exists(target2):
        move_towards(target2)
        end_turn()
    let altar_goal = closest(altar_ring)
    if contains(camp_spawns, altar_goal):
        let blocker = first( filter( camps_visible(), in_attack_range() ) )
        if exists(blocker):
            attack(blocker)
            end_turn()
    move_towards( altar_goal )
    end_turn()

let camps = camps_visible()

let camp = first( filter( camps, in_attack_range() ) )
if exists(camp):
    cast_on(0, camp)
    cast_on(1, camp)
    attack(camp)
    if ability_ready(0) and slot_is_reset(0):
        cast_self(0)
    if ability_ready(1) and slot_is_reset(1):
        cast_self(1)
    attack(camp)
    end_turn()

if team_score(ally()) == 0 and round_number() > 800:
    move_towards( closest( minus( minus( camp_spawns, respawning_visible_spawns() ), golem_tiles() ) ) )
    end_turn()
let goals = minus( minus( minus( minus( camp_spawns, respawning_visible_spawns() ), monolith_tiles() ), golem_tiles() ), mono_groups )

if contains(capturable_spawns(), position()):
    end_turn()

# claim coordination: prefer camp groups no ally has claimed, so the team spreads over the map
let free_goals = minus( goals, claimed_by_allies() )
let goal = closest( free_goals )
if not exists(goal):
    # every open group is claimed by an ally: fall back to the full goal set
    move_towards( closest(goals) )
    end_turn()
claim(goal)

# bank before a dangerous group (elk 60, wolf 20 per camp)
if exists(goal) and gems() >= 10 and group_threat(goal) >= 240 and fuel_remaining() > 65000:
    let bank_altar = first( filter( altars(), within(1, position()) ) )
    if exists(bank_altar):
        tribute(bank_altar)
        end_turn()
    move_towards( closest(safe_altar_ring) )
    end_turn()
# on a dead camp of a group not yet cleared, walk to the nearest living camp so the group can be finished
if distance(goal, position()) == 0:
    let live = nearest(camps)
    if exists(live) and not contains( union( monolith_tiles(), golem_tiles() ), unit_position(live) ):
        move_towards( unit_position(live) )
        end_turn()
if exists(goal) and distance(position(), goal) > 2 and fuel_remaining() > 65000:
    dash_to(0, goal)
    dash_to(1, goal)
move_towards( goal )
let camp2 = first( filter( camps, in_attack_range() ) )
if exists(camp2):
    attack(camp2)
set_priority( 1 + random_int(100) )
end_turn()

# team-coordination v3: per-champion roles on top of the carrier-escort v2 base.
# Plan:
# 1. HUNTERS (Vesper Vale, Marcella, Cassi): skip escort duty and run to the richest camp groups
#    (goals minus poor_spawns, i.e. goals that pay >= 15 gems). They fight only what is in reach.
# 2. GUARDS (Tavi, Ryth): escort the gem carrier when the team flag is up, and when nobody carries,
#    stay within 5 tiles of an ally instead of wandering alone.
# 3. FIGHTERS (Heart of Ruin, Vendetta, others): the focus-fire base, escort when the flag is up,
#    and farm the nearest camp group.
# 4. Carriers: whoever holds a bag tributes at the nearest safe altar, whatever its role.
# 5. Focus fire (team target, fight() reset/basic order) is unchanged for everyone.

def cast_on(slot, u):
    if ability_ready(slot):
        if slot_is_shield(slot) or slot_is_heal(slot):
            cast_self(slot)
        elif not slot_is_dash(slot):
            cast_at_unit(slot, u)

def dash_to(slot, t):
    if ability_ready(slot):
        if slot_is_dash(slot):
            dash_towards(slot, t)

# full fight turn on one champion: abilities, basic, reset, basic
def fight(u):
    if ability_ready(0):
        if slot_is_shield(0) or slot_is_heal(0):
            cast_self(0)
        elif not slot_is_dash(0) and not slot_is_reset(0):
            cast_at_unit(0, u)
    if ability_ready(1):
        if slot_is_shield(1) or slot_is_heal(1):
            cast_self(1)
        elif not slot_is_dash(1) and not slot_is_reset(1):
            cast_at_unit(1, u)
    attack(u)
    if ability_ready(0) and slot_is_reset(0):
        cast_self(0)
    if ability_ready(1) and slot_is_reset(1):
        cast_self(1)
    attack(u)
    end_turn()

# ---- draft ----
if is_draft():
    let pool = unpicked_champions()
    if available(pool, champ_vendetta()):
        pick(champ_vendetta())
    elif available(pool, champ_vesper_vale()):
        pick(champ_vesper_vale())
    elif available(pool, champ_tavi()):
        pick(champ_tavi())
    elif available(pool, champ_ryth()):
        pick(champ_ryth())
    elif available(pool, champ_ren()):
        pick(champ_ren())
    else:
        pick( random_champion(pool) )
    end_turn()

# ---- every turn ----
keep camp_spawns = camp_spawn_tiles()
keep mono_groups = group_tiles( monolith_tiles() )
keep altar_ring = ring( altars(), 1 )
keep safe_altar_ring = ring( minus( altars(), ring(monolith_tiles(), 5) ), 1 )
keep rich = rich_spawns(15)
keep poor_spawns = minus( camp_spawns, rich )
keep is_guard = i_am(champ_tavi()) or i_am(champ_ryth())
keep is_hunter = i_am(champ_vesper_vale()) or i_am(champ_marcella()) or i_am(champ_cassi_issac())

if not alive() or channeling() or (not can_move() and not can_attack()):
    end_turn()

let at_spawn = contains( spawn_region(ally()), position() )
let foes = enemies_visible()
if at_spawn:
    let shards_bought = floor( gold() / 30 )
    let treasure_n = floor( shards_bought / 2 )
    let rest_after_treasure = shards_bought - treasure_n
    let jungle_n = floor( rest_after_treasure / 2 )
    let rest_after_jungle = rest_after_treasure - jungle_n
    let strength_shards = floor( rest_after_jungle / 2 )
    buy( shard_of(family_treasure(), stat_strength()), treasure_n )
    buy( shard_of(family_jungle(), stat_health()), jungle_n )
    buy( shard(stat_strength()), strength_shards )
    buy( shard(stat_health()), rest_after_jungle - strength_shards )
    if health() < max_health() and not exists(first(filter(foes, in_attack_range()))):
        end_turn()

if not at_spawn and health() < 0.3 * max_health():
    if (in_danger() or enemies_within(8) > 0):
        let home = closest( spawn_region(ally()) )
        if fuel_remaining() > 60000:
            dash_to(0, home)
            dash_to(1, home)
        move_towards(home)
        end_turn()
    recall()
    end_turn()
if not at_spawn and gems() > 0 and health() < 0.5 * max_health() and not (in_danger() or enemies_within(8) > 0):
    recall()
    end_turn()

# team focus target: valid only while visible to this champion
let tt = team_target()
let tt_seen = exists(tt) and unit_health_frac(tt) > 0

# CAST-AHEAD: cast damage/stun at a close enemy champion before it reaches us
if exists( first(foes) ):
    let near_foe = nearest( foes )
    if exists(near_foe) and distance(position(), unit_position(near_foe)) <= 4 and not contains( spawn_region(enemy()), unit_position(near_foe) ):
        if not tt_seen:
            set_team_target(near_foe)
        if ability_ready(0) and not slot_is_dash(0) and not slot_is_shield(0) and not slot_is_heal(0) and not slot_is_reset(0):
            cast_at_unit(0, near_foe)
        if ability_ready(1) and not slot_is_dash(1) and not slot_is_shield(1) and not slot_is_heal(1) and not slot_is_reset(1):
            cast_at_unit(1, near_foe)

let enemy = weakest( filter( foes, in_attack_range() ) )
if exists(enemy) and not contains( spawn_region(enemy()), unit_position(enemy) ):
    let tt_in_reach = tt_seen and (distance(position(), unit_position(tt)) <= 1 or (i_am_ranged() and distance(position(), unit_position(tt)) <= 3))
    if tt_in_reach and not contains( spawn_region(enemy()), unit_position(tt) ):
        fight(tt)
    else:
        if not tt_seen:
            set_team_target(enemy)
        fight(enemy)

# VISION (1): free altar ward
if fuel_remaining() > 50000:
    let ward_alt = first( filter( minus( ring(altars(), 1), altars() ), within(2, position()) ) )
    if exists(ward_alt):
        place_ward(ward_alt)

# TEAM FLAG: a champion with a real bag raises byte 7; an empty-handed one with no visible carrier clears it
let flag_carrier = richest( allies_visible() )
if gems() >= 15:
    write_shared(7, 1)
elif gems() == 0 and not (exists(flag_carrier) and unit_gems(flag_carrier) >= 15):
    write_shared(7, 0)

# CARRIER: any champion with a bag tributes at the nearest safe altar
let bag_ready = gems() >= 25 or round_number() > 1500 or health() < 0.3 * max_health()
if gems() > 0 and bag_ready:
    let altar = first( filter( altars(), within(1, position()) ) )
    if exists(altar):
        tribute(altar)
        end_turn()
    let target = closest( minus( safe_altar_ring, ring(locked_altars(), 1) ) )
    if exists(target):
        move_towards(target)
        end_turn()
    let target2 = closest(safe_altar_ring)
    if exists(target2):
        move_towards(target2)
        end_turn()
    let altar_goal = closest(altar_ring)
    if contains(camp_spawns, altar_goal):
        let blocker = first( filter( camps_visible(), in_attack_range() ) )
        if exists(blocker):
            attack(blocker)
            end_turn()
    move_towards( altar_goal )
    end_turn()

# ESCORT: guards and fighters join the richest visible ally carrier when the flag is up (hunters keep hunting)
if gems() == 0 and read_shared(7) == 1 and fuel_remaining() > 40000 and not is_hunter:
    let carrier_ally = richest( allies_visible() )
    if exists(carrier_ally) and unit_gems(carrier_ally) > 0:
        if distance(position(), unit_position(carrier_ally)) > 2:
            move_towards( unit_position(carrier_ally) )
            end_turn()
        # close to the carrier: guard it, hitting camps in reach but not wandering off
        let guard_camp = first( filter( camps_visible(), in_attack_range() ) )
        if exists(guard_camp):
            attack(guard_camp)
        end_turn()

let camps = camps_visible()

let camp = first( filter( camps, in_attack_range() ) )
if exists(camp):
    cast_on(0, camp)
    cast_on(1, camp)
    attack(camp)
    if ability_ready(0) and slot_is_reset(0):
        cast_self(0)
    if ability_ready(1) and slot_is_reset(1):
        cast_self(1)
    attack(camp)
    end_turn()

# GUARD ROLE: with no bag about, a guard stays within 5 tiles of an ally rather than wandering alone
if is_guard and gems() == 0:
    let buddy = nearest( allies_visible() )
    if exists(buddy) and distance(position(), unit_position(buddy)) > 5 and fuel_remaining() > 40000:
        move_towards( unit_position(buddy) )
        end_turn()

if team_score(ally()) == 0 and round_number() > 800:
    move_towards( closest( minus( minus( camp_spawns, respawning_visible_spawns() ), golem_tiles() ) ) )
    end_turn()
let goals = minus( minus( minus( minus( camp_spawns, respawning_visible_spawns() ), monolith_tiles() ), golem_tiles() ), mono_groups )

if contains(capturable_spawns(), position()):
    if fuel_remaining() > 40000:
        let cap_ward = first( filter( minus( ring(capturable_spawns(), 2), capturable_spawns() ), within(2, position()) ) )
        if exists(cap_ward):
            place_ward(cap_ward)
    end_turn()

# HUNTER ROLE: run to the nearest rich camp group (goals that pay >= 15 gems), fighting only what is in reach
let goal_hunt = closest( minus( goals, poor_spawns ) )
if is_hunter and exists(goal_hunt) and distance(position(), goal_hunt) > 0:
    if distance(position(), goal_hunt) > 2 and fuel_remaining() > 55000:
        dash_to(0, goal_hunt)
        dash_to(1, goal_hunt)
    move_towards( goal_hunt )
    let hunt_camp = first( filter( camps, in_attack_range() ) )
    if exists(hunt_camp):
        attack(hunt_camp)
    set_priority( 1 + random_int(100) )
    end_turn()

let goal = closest(goals)
if exists(goal) and gems() >= 10 and group_threat(goal) >= 240 and fuel_remaining() > 65000:
    let bank_altar = first( filter( altars(), within(1, position()) ) )
    if exists(bank_altar):
        tribute(bank_altar)
        end_turn()
    move_towards( closest(safe_altar_ring) )
    end_turn()
if distance(goal, position()) == 0:
    let live = nearest(camps)
    if exists(live) and not contains( union( monolith_tiles(), golem_tiles() ), unit_position(live) ):
        move_towards( unit_position(live) )
        end_turn()
if exists(goal) and distance(position(), goal) > 2 and fuel_remaining() > 55000:
    dash_to(0, goal)
    dash_to(1, goal)
move_towards( goal )
let camp2 = first( filter( camps, in_attack_range() ) )
if exists(camp2):
    attack(camp2)
set_priority( 1 + random_int(100) )
end_turn()

# Plan (per-champion roles axis):
# Hunter role (Heart of Ruin, Vendetta): chases the nearest enemy champion up to 6 tiles away and uses its dash to close in.
# Everyone else keeps the shared farmer role: only fights enemies within 3 and otherwise farms camps.
# Everything else is the latest version, unchanged.

def cast_on(slot, u):
    if ability_ready(slot):
        if slot_is_shield(slot) or slot_is_heal(slot):
            cast_self(slot)
        elif not slot_is_dash(slot):
            cast_at_unit(slot, u)

def dash_to(slot, t):
    if ability_ready(slot):
        if slot_is_dash(slot):
            dash_towards(slot, t)

# engage u: hit it if in reach (3 for ranged, 1 for melee), else close in (dash when farther than 2), then hit
def hunt(u):
    set_team_target(u)
    if distance( unit_position(u), position() ) <= 1 or (i_am_ranged() and distance( unit_position(u), position() ) <= 3):
        # ranged champion pinned against its target: back off one tile and shoot next turn from range
        if i_am_ranged() and distance( unit_position(u), position() ) <= 1 and can_move():
            move_away_from( unit_position(u) )
            end_turn()
        if ability_ready(0):
            if slot_is_shield(0) or slot_is_heal(0):
                if health() < 1.01 * max_health():
                    cast_self(0)
            elif slot_is_dash(0):
                if i_am(champ_heart_of_ruin()):
                    dash_towards(0, unit_position(u))
            elif slot_is_aoe(0):
                cast_at_tile(0, unit_position(u))
            elif not slot_is_reset(0):
                cast_at_unit(0, u)
        if ability_ready(1):
            if slot_is_shield(1) or slot_is_heal(1):
                if health() < 1.01 * max_health():
                    cast_self(1)
            elif slot_is_dash(1):
                if i_am(champ_heart_of_ruin()):
                    dash_towards(1, unit_position(u))
            elif slot_is_aoe(1):
                cast_at_tile(1, unit_position(u))
            elif not slot_is_reset(1):
                cast_at_unit(1, u)
        attack(u)
        if ability_ready(0) and slot_is_reset(0):
            cast_self(0)
            attack(u)
        if ability_ready(1) and slot_is_reset(1):
            cast_self(1)
            attack(u)
        if not i_am_ranged():
            move_towards( unit_position(u) )
        end_turn()
    if distance( unit_position(u), position() ) > 1 + 1 and ability_ready(0) and slot_is_dash(0):
        dash_towards(0, unit_position(u))
    if distance( unit_position(u), position() ) > 1 + 1 and ability_ready(1) and slot_is_dash(1):
        dash_towards(1, unit_position(u))
    move_towards( unit_position(u) )
    if ability_ready(0):
        if slot_is_shield(0) or slot_is_heal(0):
            if health() < 1.01 * max_health():
                cast_self(0)
        elif slot_is_dash(0):
            if i_am(champ_heart_of_ruin()):
                dash_towards(0, unit_position(u))
        elif slot_is_aoe(0):
            cast_at_tile(0, unit_position(u))
        elif not slot_is_reset(0):
            cast_at_unit(0, u)
    if ability_ready(1):
        if slot_is_shield(1) or slot_is_heal(1):
            if health() < 1.01 * max_health():
                cast_self(1)
        elif slot_is_dash(1):
            if i_am(champ_heart_of_ruin()):
                dash_towards(1, unit_position(u))
        elif slot_is_aoe(1):
            cast_at_tile(1, unit_position(u))
        elif not slot_is_reset(1):
            cast_at_unit(1, u)
    attack(u)
    if ability_ready(0) and slot_is_reset(0):
        cast_self(0)
        attack(u)
    if ability_ready(1) and slot_is_reset(1):
        cast_self(1)
        attack(u)
    end_turn()

