keep mono_groups = group_tiles( monolith_tiles() )
keep altar_ring = ring( altars(), 1 )
keep safe_altar_ring = ring( minus( altars(), ring(monolith_tiles(), 5) ), 1 )

if not alive() or channeling() or (not can_move() and not can_attack()):
    end_turn()

let at_spawn = contains( spawn_region(ally()), position() )
let foes = enemies_visible()
if at_spawn:
    # items and stats by role
    let shards_bought = floor( gold() / 30 )
    let treasure_n = floor( shards_bought / 2 )
    let rest_after_treasure = shards_bought - treasure_n
    let jungle_n = floor( rest_after_treasure / 2 )
    let rest_after_jungle = rest_after_treasure - jungle_n
    let caster = i_am(champ_marcella()) or i_am(champ_prism()) or i_am(champ_cassi_issac()) or i_am(champ_willow())
    let tank = i_am(champ_ren()) or i_am(champ_varg())
    let main_n = floor( rest_after_jungle / 2 )
    buy( shard_of(family_treasure(), stat_strength()), treasure_n )
    buy( shard_of(family_jungle(), stat_health()), jungle_n )
    if caster:
        buy( shard(stat_focus()), main_n )
    elif tank:
        buy( shard(stat_health()), main_n )
    else:
        buy( shard(stat_strength()), main_n )
    buy( shard(stat_health()), rest_after_jungle - main_n )
    if not has_teleport() and gold() >= 40:
        buy_teleport()
    if health() < max_health() and not exists(first(filter(foes, in_attack_range()))):
        end_turn()

# retreat at 30% health when threatened; recall only when no enemy is close
if not at_spawn and health() < 0.3 * max_health():
    if (in_danger() or enemies_within(8) > 0):
        # survive first: shield if a shield slot is ready
        if ability_ready(0) and slot_is_shield(0):
            cast_self(0)
        elif ability_ready(1) and slot_is_shield(1):
            cast_self(1)
        let home = closest( spawn_region(ally()) )
        if has_teleport() and distance(position(), home) <= 3:
            teleport_to(home)
            end_turn()
        if fuel_remaining() > 60000:
            dash_to(0, home)
            dash_to(1, home)
        move_towards(home)
        end_turn()
    recall()
    end_turn()
if not at_spawn and gems() > 0 and health() < 0.5 * max_health() and not (in_danger() or enemies_within(8) > 0):
    recall()
    end_turn()

# CAST-AHEAD: stun-dash onto a close enemy, then stun/AoE it before it reaches us;
# the nearest enemy becomes the team target so allies converge on it
if exists( first(foes) ):
    let near_foe = nearest( foes )
    if exists(near_foe) and distance(position(), unit_position(near_foe)) <= 4 and not contains( spawn_region(enemy()), unit_position(near_foe) ):
        set_team_target(near_foe)
        # stun dash closes distance so the stun lands right away
        if slot_is_dash(0) and slot_stun(0) > 0 and distance(position(), unit_position(near_foe)) >= 2 and fuel_remaining() > 60000:
            dash_to(0, unit_position(near_foe))
        if ability_ready(1) and slot_radius(1) >= 2 and slot_is_aoe(1) and not slot_is_dash(1) and not slot_is_shield(1) and not slot_is_heal(1) and not slot_is_reset(1) and distance(position(), unit_position(near_foe)) <= slot_range(1) and enemies_within(slot_radius(1)) >= 2:
            cast_at_tile(1, unit_position(near_foe))
        else:
            cast_foe(near_foe)

# HEAL ALLY: heal slots go to the weakest hurt visible ally in range (never to an enemy)
if (ability_ready(0) and slot_is_heal(0)) or (ability_ready(1) and slot_is_heal(1)):
    let hurt = weakest( allies_visible() )
    if exists(hurt) and unit_health_frac(hurt) < 0.6:
        if ability_ready(0) and slot_is_heal(0) and distance(position(), unit_position(hurt)) <= slot_range(0):
            cast_at_unit(0, hurt)
        elif ability_ready(1) and slot_is_heal(1) and distance(position(), unit_position(hurt)) <= slot_range(1):
            cast_at_unit(1, hurt)

# focus fire: all allies pick the weakest in-range enemy
let enemy = weakest( filter( foes, in_attack_range() ) )
if exists(enemy) and not contains( spawn_region(enemy()), unit_position(enemy) ):
    # shield up when hurt in a fight
    if health() < 0.5 * max_health():
        if ability_ready(0) and slot_is_shield(0):
            cast_self(0)
        elif ability_ready(1) and slot_is_shield(1):
            cast_self(1)
    # AoE first when the enemy is clustered, so one cast hits several foes
    if ability_ready(1) and slot_is_aoe(1) and slot_radius(1) >= 2 and enemies_within(slot_radius(1)) >= 2 and not slot_is_dash(1) and not slot_is_shield(1) and not slot_is_heal(1) and not slot_is_reset(1):
        cast_at_tile(1, unit_position(enemy))
    cast_on(0, enemy)
    cast_on(1, enemy)
    attack(enemy)
    # reset after the basic attack, then swing again
    if ability_ready(0) and slot_is_reset(0):
        cast_self(0)
    if ability_ready(1) and slot_is_reset(1):
        cast_self(1)
    attack(enemy)
    end_turn()

# outnumbered: an enemy is close but the local fight favours them, so step away instead of walking in
let nf = nearest( foes )
if exists(nf) and distance(position(), unit_position(nf)) <= 5 and local_strength(6) < 0.8 and not contains( spawn_region(enemy()), unit_position(nf) ):
    move_away_from( unit_position(nf) )
    end_turn()

# tribute only with a worthwhile bag (or when hurt / late game)
let bag_ready = gems() >= 25 or round_number() > 1500 or health() < 0.3 * max_health()
if gems() > 0 and bag_ready:
    let altar = first( filter( altars(), within(1, position()) ) )
    if exists(altar):
        tribute(altar)
        end_turn()
    let target = closest( minus( safe_altar_ring, ring(locked_altars(), 1) ) )
    if exists(target):
        move_towards(target)
        end_turn()
    let target2 = closest(safe_altar_ring)
    if exists(target2):
        move_towards(target2)
        end_turn()
    let altar_goal = closest(altar_ring)
    if contains(camp_spawns, altar_goal):
        let blocker = first( filter( camps_visible(), in_attack_range() ) )
        if exists(blocker):
            attack(blocker)
            end_turn()
    move_towards( altar_goal )
    end_turn()

let camps = camps_visible()

let camp = first( filter( camps, in_attack_range() ) )
if exists(camp):
    # camps: AoE when a cluster is in radius, stun/damage otherwise
    if ability_ready(1) and slot_is_aoe(1) and slot_radius(1) >= 2 and not slot_is_dash(1) and not slot_is_shield(1) and not slot_is_heal(1) and not slot_is_reset(1):
        cast_at_tile(1, unit_position(camp))
    cast_on(0, camp)
    cast_on(1, camp)
    attack(camp)
    if ability_ready(0) and slot_is_reset(0):
        cast_self(0)
    if ability_ready(1) and slot_is_reset(1):
        cast_self(1)
    attack(camp)
    end_turn()

if team_score(ally()) == 0 and round_number() > 800:
    move_towards( closest( minus( minus( camp_spawns, respawning_visible_spawns() ), golem_tiles() ) ) )
    end_turn()
let goals = minus( minus( minus( minus( camp_spawns, respawning_visible_spawns() ), monolith_tiles() ), golem_tiles() ), mono_groups )

if contains(capturable_spawns(), position()):
    end_turn()

# claim coordination: prefer camp groups no ally has claimed, so the team spreads over the map
let free_goals = minus( goals, claimed_by_allies() )
let goal = closest( free_goals )
if not exists(goal):
    move_towards( closest(goals) )
    end_turn()
claim(goal)

# bank before a dangerous group (elk 60, wolf 20 per camp)
if exists(goal) and gems() >= 10 and group_threat(goal) >= 240 and fuel_remaining() > 65000:
    let bank_altar = first( filter( altars(), within(1, position()) ) )
    if exists(bank_altar):
        tribute(bank_altar)
        end_turn()
    move_towards( closest(safe_altar_ring) )
    end_turn()
# on a dead camp of a group not yet cleared, walk to the nearest living camp so the group can be finished
if distance(goal, position()) == 0:
    let live = nearest(camps)
    if exists(live) and not contains( union( monolith_tiles(), golem_tiles() ), unit_position(live) ):
        move_towards( unit_position(live) )
        end_turn()
if exists(goal) and distance(position(), goal) > 2 and fuel_remaining() > 65000:
    dash_to(0, goal)
    dash_to(1, goal)
move_towards( goal )
let camp2 = first( filter( camps, in_attack_range() ) )
if exists(camp2):
    attack(camp2)
set_priority( 1 + random_int(100) )
end_turn()

# Plan (mobility-escape-v2): v0 plus one mobility change, fuel-gated.
# 1. Teleport crystals stay on the spawn buy and hop onto altars 2-3 tiles away (unchanged).
# 2. Dashes are an escape: when a visible enemy is within 3 and we are below 40% health, fire any
#    ready dash toward spawn before stepping away, so a low champion does not die in a 1-on-1.
# 3. Recall is kept for safe banking only (never cast with an enemy within 8), since damage cancels it.
# 4. Dash casts are guarded by ability_ready and slot_is_dash, and by fuel_remaining() > 60000.

# zg14: ability-type-aware casting from hybrid #14 (Opus): shield/heal on self, dash kept for escape/travel
def cast_on(slot, u):
    if ability_ready(slot):
        if slot_is_shield(slot) or slot_is_heal(slot):
            cast_self(slot)
        elif not slot_is_dash(slot):
            cast_at_unit(slot, u)

def dash_to(slot, t):
    if ability_ready(slot):
        if slot_is_dash(slot):
            dash_towards(slot, t)

# ---- draft ----
if is_draft():
    let pool = unpicked_champions()
    if available(pool, champ_vendetta()):
        write_draft("V")
        pick(champ_vendetta())
    elif available(pool, champ_vesper_vale()):
        write_draft("W")
        pick(champ_vesper_vale())
    elif available(pool, champ_tavi()):
        write_draft("T")
        pick(champ_tavi())
    elif available(pool, champ_ryth()):
        write_draft("R")
        pick(champ_ryth())
    elif available(pool, champ_ren()):
        write_draft("N")
        pick(champ_ren())
    else:
        pick( random_champion(pool) )
    end_turn()

# ---- every turn ----
keep camp_spawns = camp_spawn_tiles()
# monolith groups never change: one group_tiles() per game (fuel; bot-session check)
keep mono_groups = group_tiles( monolith_tiles() )
keep altar_ring = ring( altars(), 1 )
keep safe_altar_ring = ring( minus( altars(), ring(monolith_tiles(), 5) ), 1 )
# elk spawn tiles are static: bind once for the early-game route
keep elk_spawns = elk_tiles()

if not alive() or channeling() or (not can_move() and not can_attack()):
    end_turn()

# VISION: free ward on an altar within reach (place_ward works within 2 tiles; it recharges, so
# placing whenever we pass an altar keeps a sight line over the tribute spot). Does not end the turn.
let ward_altar = first( filter( altars(), within(2, position()) ) )
if exists(ward_altar):
    place_ward(ward_altar)
else:
    # no altar in reach: when enemies are close, ward a bush tile within 2 to see into the fog
    # around the fight (fuel-gated, the bush scan is a board query)
    if fuel_remaining() > 40000 and enemies_within(8) > 0:
        let ward_bush = first( filter( bushes(), within(2, position()) ) )
        if exists(ward_bush):
            place_ward(ward_bush)

let at_spawn = contains( spawn_region(ally()), position() )
# one enemies_visible() query per turn, reused below (no move happens before its last use)
let foes = enemies_visible()
if at_spawn:
    let shards_bought = floor( gold() / 30 )
    let treasure_n = floor( shards_bought / 2 )
    let rest_after_treasure = shards_bought - treasure_n
    let jungle_n = floor( rest_after_treasure / 2 )
    let rest_after_jungle = rest_after_treasure - jungle_n
    let strength_shards = floor( rest_after_jungle / 2 )
    buy( shard_of(family_treasure(), stat_strength()), treasure_n )
    buy( shard_of(family_jungle(), stat_health()), jungle_n )
    buy( shard(stat_strength()), strength_shards )
    buy( shard(stat_health()), rest_after_jungle - strength_shards )
    # MOBILITY: a teleport crystal (10 gold) from the gold left after the shard buys
    if not has_teleport() and gold() - 30 * shards_bought >= 10:
        buy_teleport()
    # heal on spawn before heading back out, unless an enemy is already in reach
    if health() < max_health() and not exists(first(filter(foes, in_attack_range()))):
        end_turn()

# retreat at 30% health normally; safe recall: never start a recall with an enemy champion within 8
if not at_spawn and health() < 0.3 * max_health():
    if (in_danger() or enemies_within(8) > 0):
        let home = closest( spawn_region(ally()) )
        # fuel gate: a long retreat's dash search can push the turn past 100k
        if fuel_remaining() > 60000:
            dash_to(0, home)
            dash_to(1, home)
        move_towards(home)
        end_turn()
    recall()
    end_turn()
# bank the bag early when hurt and nothing is near
if not at_spawn and gems() > 0 and health() < 0.5 * max_health() and not (in_danger() or enemies_within(8) > 0):
    recall()
    end_turn()

# CAST-AHEAD: cast damage/stun at a close enemy champion before it reaches us, without moving
if exists( first(foes) ):
    let near_foe = nearest( foes )
    if exists(near_foe) and distance(position(), unit_position(near_foe)) <= 4 and not contains( spawn_region(enemy()), unit_position(near_foe) ):
        set_team_target(near_foe)
        if ability_ready(0) and not slot_is_dash(0) and not slot_is_shield(0) and not slot_is_heal(0):
            cast_at_unit(0, near_foe)
        if ability_ready(1) and not slot_is_dash(1) and not slot_is_shield(1) and not slot_is_heal(1):
            cast_at_unit(1, near_foe)

let enemy = weakest( filter( foes, in_attack_range() ) )
# an enemy on its own spawn is healed every turn: fighting it there never ends
if exists(enemy) and not contains( spawn_region(enemy()), unit_position(enemy) ):
    cast_on(0, enemy)
    cast_on(1, enemy)
    attack(enemy)
    if ability_ready(0) and slot_is_reset(0):
        cast_self(0)
    if ability_ready(1) and slot_is_reset(1):
        cast_self(1)
    attack(enemy)
    end_turn()

# ESCAPE DASH (mobility): badly hurt with a visible enemy within 3 -> dash toward spawn, then step away
if enemies_within(3) > 0 and health() < 0.4 * max_health() and fuel_remaining() > 60000:
    dash_to(0, closest( spawn_region(ally()) ))
    dash_to(1, closest( spawn_region(ally()) ))
    if exists(first(foes)):
        move_away_from( unit_position( nearest(foes) ) )
        end_turn()

# tribute only with a worthwhile bag (or when hurt / late game)
let bag_ready = gems() >= 25 or round_number() > 1500 or health() < 0.3 * max_health()
if gems() > 0 and bag_ready:
    # an altar next to us works even when locked: tributing there attacks the lock (5 hits clear it)
    let altar = first( filter( altars(), within(1, position()) ) )
    if exists(altar):
        tribute(altar)
        end_turn()
    # walk to an open altar out of monolith reach (5); else any altar out of reach; else any altar
    let target = closest( minus( safe_altar_ring, ring(locked_altars(), 1) ) )
    if exists(target):
        # MOBILITY: with a teleport crystal, hop straight onto a target 2-3 tiles away
        if has_teleport() and not channeling() and distance(position(), target) >= 2 and distance(position(), target) <= 3:
            teleport_to(target)
            end_turn()
        move_towards(target)
        end_turn()
    let target2 = closest(safe_altar_ring)
    if exists(target2):
        move_towards(target2)
        end_turn()
    let altar_goal = closest(altar_ring)
    # every altar-adjacent tile is taken by a camp: fight it
    if contains(camp_spawns, altar_goal):
        let blocker = first( filter( camps_visible(), in_attack_range() ) )
        if exists(blocker):
            attack(blocker)
            end_turn()
    move_towards( altar_goal )
    end_turn()

# one camps_visible() query per turn, reused for both attack checks
let camps = camps_visible()

let camp = first( filter( camps, in_attack_range() ) )
# FIGHT TIMING with ESCAPE DASH: a camp in reach is not worth dying for. If visible enemies are close
# and the local fight is unfavourable, dash toward our spawn region if a dash is ready (fuel-gated),
# then step away from the nearest enemy instead of hitting the camp.
if exists(camp) and enemies_within(5) > 0 and local_strength(5) < 0.8:
    let escape_home = closest( spawn_region(ally()) )
    if fuel_remaining() > 60000:
        dash_to(0, escape_home)
        dash_to(1, escape_home)
    move_away_from( unit_position( nearest(foes) ) )
    end_turn()
if exists(camp):
    cast_on(0, camp)
    cast_on(1, camp)
    attack(camp)
    # attack reset on camps too: a second basic attack after the first
    if ability_ready(0) and slot_is_reset(0):
        cast_self(0)
    if ability_ready(1) and slot_is_reset(1):
        cast_self(1)
    attack(camp)
    end_turn()

# nothing tributed by round 800: the monolith takers go for monoliths
if team_score(ally()) == 0 and round_number() > 800 and (i_am(champ_heart_of_ruin()) or i_am(champ_vendetta()) or i_am(champ_vesper_vale())):
    move_towards( closest( minus( minus( camp_spawns, respawning_visible_spawns() ), golem_tiles() ) ) )
    end_turn()

# monolith commit: after round 1000 the taker role claims the closest free monolith, and walks in
# only when two allies already claim it and we are healthy. Farmers never take monoliths.
if round_number() > 1000 and fuel_remaining() > 55000 and (i_am(champ_heart_of_ruin()) or i_am(champ_vendetta()) or i_am(champ_vesper_vale())):
    let mono_goal = closest( minus( monolith_tiles(), respawning_visible_spawns() ) )
    if exists(mono_goal):
        claim(mono_goal)
        if claim_count(mono_goal) >= 2 and health() >= 0.8 * max_health():
            move_towards(mono_goal)
            end_turn()

let goals = minus( minus( minus( minus( camp_spawns, respawning_visible_spawns() ), monolith_tiles() ), golem_tiles() ), mono_groups )

# EARLY ROUTE (tune line: early-wolf-v1): before round 250 skip elk groups (60 str each) and walk to
# the nearest wolf, gem cluster or gold camp. Healthy farmers only.
if round_number() < 250 and health() >= 0.7 * max_health():
    let early_goal = closest( minus( goals, elk_spawns ) )
    if exists(early_goal) and distance(position(), early_goal) > 0:
        move_towards(early_goal)
        end_turn()

# already standing on a cleared camp spawn: hold here so the capture timer keeps running
if contains(capturable_spawns(), position()):
    end_turn()

let goal = closest(goals)
# bank before a dangerous group (elk 60, wolf 20 per camp)
# fuel guard: the bank walk is a second distance query this turn
if exists(goal) and gems() >= 10 and group_threat(goal) >= 240 and fuel_remaining() > 65000:
    let bank_altar = first( filter( altars(), within(1, position()) ) )
    if exists(bank_altar):
        tribute(bank_altar)
        end_turn()
    move_towards( closest(safe_altar_ring) )
    end_turn()
# on a dead camp of a group that is not cleared yet, walk to the nearest living camp
# (not a monolith or golem) so the group can be finished
if distance(goal, position()) == 0:
    let live = nearest(camps)
    if exists(live) and not contains( union( monolith_tiles(), golem_tiles() ), unit_position(live) ):
        move_towards( unit_position(live) )
        end_turn()
# dash toward a camp goal only when it is farther than 2 tiles (fuel-gated)
if exists(goal) and distance(position(), goal) > 2 and fuel_remaining() > 55000:
    dash_to(0, goal)
    dash_to(1, goal)
move_towards( goal )
let camp2 = first( filter( camps, in_attack_range() ) )
if exists(camp2):
    attack(camp2)
set_priority( 1 + random_int(100) )
end_turn()

# team-coordination v3 + OUTNUMBERED DISENGAGE (combat micro).
# Most early deaths are 2+ of theirs on 1 of ours. A champion that sees 2+ enemies within
# 5 tiles while local_strength says the fight is lost (<0.8):
# 1. throws any stun at the nearest foe to buy a step;
# 2. if melee, takes a free hit on the weakest foe in reach (melee can hit and walk);
# 3. falls back towards the nearest visible ally, or towards spawn if no ally is near,
#    instead of trading alone.
# Everything else is unchanged.

def cast_on(slot, u):
    if ability_ready(slot):
        if slot_is_shield(slot) or slot_is_heal(slot):
            cast_self(slot)
        elif not slot_is_dash(slot):
            cast_at_unit(slot, u)

def dash_to(slot, t):
    if ability_ready(slot):
        if slot_is_dash(slot):
            dash_towards(slot, t)

# full fight turn on one champion: abilities, basic, reset, basic
def fight(u):
    if ability_ready(0):
        if slot_is_shield(0) or slot_is_heal(0):
            cast_self(0)
        elif not slot_is_dash(0) and not slot_is_reset(0):
            cast_at_unit(0, u)
    if ability_ready(1):
        if slot_is_shield(1) or slot_is_heal(1):
            cast_self(1)
        elif not slot_is_dash(1) and not slot_is_reset(1):
            cast_at_unit(1, u)
    attack(u)
    if ability_ready(0) and slot_is_reset(0):
        cast_self(0)
    if ability_ready(1) and slot_is_reset(1):
        cast_self(1)
    attack(u)
    end_turn()

# ---- draft ----
if is_draft():
