# Plan (ability-axis v1): abilities decide fights, so the change is about how we cast.
# 1. Type-aware casting: a shield or heal goes on self or the weakest visible ally, an AoE is
#    cast at the target tile, a stun or damage is cast at the unit, and a reset is never cast at an enemy.
# 2. Stun before burst: the cast-ahead block now uses the same typed casting, so openers land from range 4.
# 3. Reset after a basic: unchanged (basic, self-cast reset, basic).
# 4. set_priority (turn order next round): a champion with a ready stun whose reach covers a visible
#    enemy acts first (200), a badly hurt one acts last (1) so it can retreat, others are random.
#    Setting it early in the turn means it is applied even on turns that end in a fight.

# zg14 base: ability-type-aware casting
def cast_on(slot, u):
    if ability_ready(slot):
        if slot_is_heal(slot):
            # heal the weakest visible ally, or ourselves when no ally is visible
            if exists(weakest(allies_visible())):
                cast_at_unit(slot, weakest(allies_visible()))
            else:
                cast_self(slot)
        elif slot_is_shield(slot):
            cast_self(slot)
        elif slot_is_reset(slot):
            # resets are self-cast after a basic attack, never at an enemy
            pass
        elif slot_is_dash(slot):
            # dashes are reserved for escape and travel
            pass
        elif slot_is_aoe(slot) and slot_radius(slot) > 0:
            # area abilities hit the target tile, catching neighbours too
            cast_at_tile(slot, unit_position(u))
        else:
            cast_at_unit(slot, u)

def dash_to(slot, t):
    if ability_ready(slot):
        if slot_is_dash(slot):
            dash_towards(slot, t)

