    if ability_ready(slot):
        if slot_is_shield(slot) or slot_is_heal(slot):
            cast_self(slot)
        elif not slot_is_dash(slot):
            cast_at_unit(slot, u)

# stun before burst: a ready stun (slot_stun > 0) on the target goes first
def stun_first(u):
    if ability_ready(0) and slot_stun(0) > 0 and not slot_is_dash(0) and not slot_is_shield(0) and not slot_is_heal(0):
        cast_at_unit(0, u)
    elif ability_ready(1) and slot_stun(1) > 0 and not slot_is_dash(1) and not slot_is_shield(1) and not slot_is_heal(1):
        cast_at_unit(1, u)

def dash_to(slot, t):
    if ability_ready(slot):
        if slot_is_dash(slot):
            dash_towards(slot, t)

