# Plan (team-coordination v1): use the one free shared byte (7) as a team push flag.
# 1. Byte 7 = 1 means "a healthy group of allies is together": champions that see >= 2 allies
#    within 6 and are at >= 80% health write it after round 1000.
# 2. Monolith commit: a champion goes to the monolith when the flag is up, not only when
#    2+ allies have claimed the same monolith, so a group that gathers pushes together.
# 3. Focus: the attacker sets the team target to the enemy it hits, so cast-ahead and
#    the other allies pile onto the same champion.
# 4. Turn order, retreat, banking and altar logic are unchanged from v0.

# zg14 base: ability-type-aware casting
def cast_on(slot, u):
    if ability_ready(slot):
        if slot_is_heal(slot):
            # heal the weakest visible ally, or ourselves when no ally is visible
            if exists(weakest(allies_visible())):
                cast_at_unit(slot, weakest(allies_visible()))
            else:
                cast_self(slot)
        elif slot_is_shield(slot):
            cast_self(slot)
        elif slot_is_reset(slot):
            # resets are self-cast after a basic attack, never at an enemy
            pass
        elif slot_is_dash(slot):
            # dashes are reserved for escape and travel
            pass
        elif slot_is_aoe(slot) and slot_radius(slot) > 0:
            # area abilities hit the target tile, catching neighbours too
            cast_at_tile(slot, unit_position(u))
        else:
            cast_at_unit(slot, u)

def dash_to(slot, t):
    if ability_ready(slot):
        if slot_is_dash(slot):
            dash_towards(slot, t)

