# 1. FIRST HIT: stun-dashers (Heart of Ruin) open with the dash onto a close foe, and champions in a fight
#    raise set_priority so they act first next round.
# 2. 2v1 FOCUS: a healthy champion steps toward a team target just out of reach (chase only 1-2 tiles,
#    with an ally near or when the target is low), so both allies hit the same enemy on the same turn.
# 3. KITE: a hurt ranged champion with an enemy adjacent and an ally near steps away instead of trading in place.
# 4. Thresholds are named constants (CHASE_HP, KITE_HP, PRIO_FIGHT) for tuning.

def cast_on(slot, u):
    if ability_ready(slot):
        if slot_is_shield(slot) or slot_is_heal(slot):
            cast_self(slot)
        elif not slot_is_dash(slot):
            cast_at_unit(slot, u)

def dash_to(slot, t):
    if ability_ready(slot):
        if slot_is_dash(slot):
            dash_towards(slot, t)

# full fight turn on one champion: abilities, basic, reset, basic; claim first move next round
def fight(u):
    if ability_ready(0):
        if slot_is_shield(0) or slot_is_heal(0):
            cast_self(0)
        elif not slot_is_dash(0) and not slot_is_reset(0):
            cast_at_unit(0, u)
    if ability_ready(1):
        if slot_is_shield(1) or slot_is_heal(1):
            cast_self(1)
        elif not slot_is_dash(1) and not slot_is_reset(1):
            cast_at_unit(1, u)
    attack(u)
    if ability_ready(0) and slot_is_reset(0):
        cast_self(0)
    if ability_ready(1) and slot_is_reset(1):
        cast_self(1)
    attack(u)
