# 1. Stun before burst: stun slots fire first at the nearest engaged enemy, and stun-dashes (Heart of Ruin) close distance onto a foe to set up the stun.
# 2. AoE on clusters: area slots are aimed at the enemy tile when two or more enemies sit inside the slot radius, otherwise single-target slots go to the weakest enemy in range.
# 3. Survive: shields are self-cast when hurt in a fight, and heal slots restore the weakest hurt ally (tanks and healers keep the team alive through trades).
# 4. Reset: self-cast reset slots after the first basic attack, then attack again.
# Macro change (monolith commit): after round 1000, a healthy champion carrying few gems
# joins the nearest monolith once an ally already claims it. Heart of Ruin seeds the claim,
# so the team gathers on one monolith instead of spreading out.
# Combat, retreat, claims, tribute and camp logic otherwise follow v1.

# ability choice vs one target: damage or stun slots only, respecting range and type
def cast_on(slot, u):
    if ability_ready(slot) and not slot_is_dash(slot) and not slot_is_heal(slot) and not slot_is_reset(slot):
        if slot_is_shield(slot):
            if distance(position(), unit_position(u)) <= 3:
                cast_self(slot)
        elif distance(position(), unit_position(u)) <= slot_range(slot):
            if slot_is_aoe(slot):
                cast_at_tile(slot, unit_position(u))
            else:
                cast_at_unit(slot, u)

# ability choice vs one enemy: stun slot first (stun before burst), else the other offensive slot
def cast_foe(u):
    if ability_ready(0) and slot_stun(0) > 0 and not slot_is_dash(0) and not slot_is_shield(0) and not slot_is_heal(0) and not slot_is_reset(0) and distance(position(), unit_position(u)) <= slot_range(0):
        if slot_is_aoe(0):
            cast_at_tile(0, unit_position(u))
        else:
            cast_at_unit(0, u)
    elif ability_ready(1) and not slot_is_dash(1) and not slot_is_shield(1) and not slot_is_heal(1) and not slot_is_reset(1) and distance(position(), unit_position(u)) <= slot_range(1):
        if slot_is_aoe(1):
            cast_at_tile(1, unit_position(u))
        else:
            cast_at_unit(1, u)
    elif ability_ready(0) and not slot_is_dash(0) and not slot_is_shield(0) and not slot_is_heal(0) and not slot_is_reset(0) and distance(position(), unit_position(u)) <= slot_range(0):
