# combat micro plan:
# 1. Open each fight: a melee champ with the nearest foe inside ~4 tiles and a favourable local fight casts its opener (stun slot first), then steps in and attacks on the same turn.
# 2. Ranged champs (Cassi, Marcella, Prism, Willow) kite: if a foe is within 2 tiles they cast, then step back out of reach; at 4-6 tiles they close to attack range 3.
# 3. The whole team focuses the weakest enemy in attack range, so attacks converge and kills come fast.
# 4. Retreat/regroup: when outnumbered (local_strength < 0.8) step away instead of walking in.
# 5. Never idle when a foe is near: if a turn would end without an attack or a move toward the fight, move toward the nearest enemy or the goal.
# 6. VISION (new): with no enemy within 6, the free ward goes on the nearest altar within 3 every turn it recharges,
#    so allies see incoming enemies through the fog. Rangers hold back behind the vision line when a fight starts.
# Everything else (drafting, roles, purchases, claims, tribute, camp logic) is unchanged from v1.

# ability choice vs one target: damage or stun slots only, respecting range and type
def cast_on(slot, u):
    if ability_ready(slot) and not slot_is_dash(slot) and not slot_is_heal(slot) and not slot_is_reset(slot):
        if slot_is_shield(slot):
            if distance(position(), unit_position(u)) <= 3:
                cast_self(slot)
        elif distance(position(), unit_position(u)) <= slot_range(slot):
            if slot_is_aoe(slot):
                cast_at_tile(slot, unit_position(u))
            else:
                cast_at_unit(slot, u)

# ability choice vs one enemy: stun slot first (open with cc), else the other offensive slot
def cast_foe(u):
    if ability_ready(0) and slot_stun(0) > 0 and not slot_is_dash(0) and not slot_is_shield(0) and not slot_is_heal(0) and not slot_is_reset(0) and distance(position(), unit_position(u)) <= slot_range(0):
        if slot_is_aoe(0):
            cast_at_tile(0, unit_position(u))
        else:
            cast_at_unit(0, u)
    elif ability_ready(1) and not slot_is_dash(1) and not slot_is_shield(1) and not slot_is_heal(1) and not slot_is_reset(1) and distance(position(), unit_position(u)) <= slot_range(1):
        if slot_is_aoe(1):
            cast_at_tile(1, unit_position(u))
        else:
            cast_at_unit(1, u)
    elif ability_ready(0) and not slot_is_dash(0) and not slot_is_shield(0) and not slot_is_heal(0) and not slot_is_reset(0) and distance(position(), unit_position(u)) <= slot_range(0):
        if slot_is_aoe(0):
            cast_at_tile(0, unit_position(u))
        else:
            cast_at_unit(0, u)

def dash_to(slot, t):
    if ability_ready(slot):
        if slot_is_dash(slot):
            dash_towards(slot, t)

