# TEAM SPLIT PLAN (shared-memory coordination):
# 1. Non-hunters claim the nearest camp group no ally has claimed (claimed_by_allies), so the team spreads over the map instead of stacking on one camp.
# 2. Claims are released implicitly: a claim is replaced each turn, so an abandoned group reopens.
# 3. Byte 7 keeps the bag flag: a carrier raises it, and the escort rule pulls guards and fighters to the richest visible carrier.
# 4. Hunters keep their rich-camp run and do not take the open-goal split.
# 5. Monolith commit (after round 1000) still gathers 2+ allies on one monolith group before walking in.

def cast_on(slot, u):
    if ability_ready(slot):
        if slot_is_shield(slot) or slot_is_heal(slot):
            cast_self(slot)
        elif not slot_is_dash(slot):
            cast_at_unit(slot, u)

def dash_to(slot, t):
    if ability_ready(slot):
        if slot_is_dash(slot):
            dash_towards(slot, t)

# full fight turn on one champion: abilities, basic, reset, basic
def fight(u):
    if ability_ready(0):
        if slot_is_shield(0) or slot_is_heal(0):
            cast_self(0)
        elif not slot_is_dash(0) and not slot_is_reset(0):
            cast_at_unit(0, u)
    if ability_ready(1):
        if slot_is_shield(1) or slot_is_heal(1):
            cast_self(1)
        elif not slot_is_dash(1) and not slot_is_reset(1):
            cast_at_unit(1, u)
    attack(u)
    if ability_ready(0) and slot_is_reset(0):
        cast_self(0)
    if ability_ready(1) and slot_is_reset(1):
        cast_self(1)
    attack(u)
    end_turn()

