# Plan (abilities v3: stun first, then burst; heals and shields used on purpose):
# 1. Stun before burst. When we engage a champion, any slot with slot_stun > 0 is cast first,
#    then the damage slot.
# 2. Range-aware casting. Damage and AoE only fire when the target is within
#    slot_range + slot_radius, so cooldowns are not wasted out of reach.
#    AoE is cast at the target's tile.
# 3. Stuns are saved for champions. While an enemy champion is visible, a stun slot is not
#    spent on a camp.
# 4. Support role.
#    - A heal slot heals the weakest visible ally under 60%, at the start of the turn.
#    - Otherwise it heals the champion itself under 75%.
#    - Shields are self-cast only when hurt or with an enemy within 4.
# 5. VISION (this version): the free ward on an altar is taken from within 3 tiles, not 2,
#    so the ward goes down on the altar we are walking past. Bush wards still cover fog fights.
# 6. Everything else (routing, banking, monolith roles, draft) is unchanged from v1.

def cast_on(slot, u):
    if ability_ready(slot):
        if slot_is_heal(slot):
            if exists(weakest(allies_visible())) and unit_health_frac(weakest(allies_visible())) < 0.6:
                cast_at_unit(slot, weakest(allies_visible()))
            elif health() < 0.75 * max_health():
                cast_self(slot)
        elif slot_is_shield(slot):
            if health() < 0.85 * max_health() or enemies_within(4) > 0:
                cast_self(slot)
        elif slot_is_reset(slot):
            pass
        elif slot_is_dash(slot):
            pass
        elif distance(position(), unit_position(u)) <= slot_range(slot) + slot_radius(slot) + 1:
            if slot_is_aoe(slot) and slot_radius(slot) > 0:
                cast_at_tile(slot, unit_position(u))
            else:
                cast_at_unit(slot, u)

def dash_to(slot, t):
    if ability_ready(slot):
        if slot_is_dash(slot):
            dash_towards(slot, t)

