# ABILITY PLAN (this version):
# 1. One ability per turn, so pick the right one: a ready stun goes first (stun before burst), then AoE at the target tile.
# 2. Shields and heals fire only when health is under 60%, so they are not wasted at full health.
# 3. Single-target damage abilities come after stun and AoE; reset is cast after the first basic, then a second basic.
# 4. Cast-ahead and the outnumbered disengage stun are kept; macro structure and let count are unchanged.

def cast_on(slot, u):
    if ability_ready(slot):
        if slot_is_shield(slot) or slot_is_heal(slot):
            cast_self(slot)
        elif not slot_is_dash(slot):
            cast_at_unit(slot, u)

def dash_to(slot, t):
    if ability_ready(slot):
        if slot_is_dash(slot):
            dash_towards(slot, t)

# full fight turn on one champion: stun -> AoE -> defensive -> damage, basic, reset, basic
def fight(u):
    if ability_ready(0) and slot_stun(0) > 0 and not slot_is_dash(0):
        cast_at_unit(0, u)
    elif ability_ready(1) and slot_stun(1) > 0 and not slot_is_dash(1):
        cast_at_unit(1, u)
    elif ability_ready(0) and slot_is_aoe(0) and not slot_is_dash(0):
        cast_at_tile(0, unit_position(u))
    elif ability_ready(1) and slot_is_aoe(1) and not slot_is_dash(1):
        cast_at_tile(1, unit_position(u))
    elif ability_ready(0) and (slot_is_shield(0) or slot_is_heal(0)) and health() < 0.6 * max_health():
        cast_self(0)
    elif ability_ready(1) and (slot_is_shield(1) or slot_is_heal(1)) and health() < 0.6 * max_health():
        cast_self(1)
    elif ability_ready(0) and slot_is_damage(0) and not slot_is_dash(0):
        cast_at_unit(0, u)
    elif ability_ready(1) and slot_is_damage(1) and not slot_is_dash(1):
        cast_at_unit(1, u)
    attack(u)
    if ability_ready(0) and slot_is_reset(0):
        cast_self(0)
    if ability_ready(1) and slot_is_reset(1):
        cast_self(1)
    attack(u)
    end_turn()

