# PAIRS plan (v0 + pairing):
# 1. Pairs: vendetta with vesper_vale (pair 1), tavi with ryth (pair 2), others are pair 3.
# 2. Beacon: a champion that sees an enemy champion within 6 writes its pair id into shared byte 7.
#    The beacon is cleared again by the same pair once the fight is over.
# 3. Converge: a champion that is not in a fight, whose pair has the beacon set, walks toward the
#    nearest camp group an ally claims (within 12 tiles), so partners regroup on the fight.
# 4. Claims: each farming champion claims the camp it walks to, so partners farm neighbouring groups
#    and can find each other's position without vision.
# 5. Everything else (support, stun-first casting, banking, monolith roles, draft) is unchanged.

def cast_on(slot, u):
    if ability_ready(slot):
        if slot_is_heal(slot):
            if exists(weakest(allies_visible())) and unit_health_frac(weakest(allies_visible())) < 0.6:
                cast_at_unit(slot, weakest(allies_visible()))
            elif health() < 0.75 * max_health():
                cast_self(slot)
        elif slot_is_shield(slot):
            if health() < 0.85 * max_health() or enemies_within(4) > 0:
                cast_self(slot)
        elif slot_is_reset(slot):
            pass
        elif slot_is_dash(slot):
            pass
        elif distance(position(), unit_position(u)) <= slot_range(slot) + slot_radius(slot) + 1:
            if slot_is_aoe(slot) and slot_radius(slot) > 0:
                cast_at_tile(slot, unit_position(u))
            else:
                cast_at_unit(slot, u)

def dash_to(slot, t):
    if ability_ready(slot):
        if slot_is_dash(slot):
            dash_towards(slot, t)

# farm toward a chosen camp (no lets inside: it is expanded twice)
def go_camp(goal):
    if exists(goal) and gems() >= 10 and group_threat(goal) >= 240 and fuel_remaining() > 65000:
        if exists(first(filter(altars(), within(1, position())))):
            tribute(first(filter(altars(), within(1, position()))))
            end_turn()
        move_towards(closest(safe_altar_ring))
        end_turn()
    if distance(goal, position()) == 0:
        if exists(nearest(camps)) and not contains(union(monolith_tiles(), golem_tiles()), unit_position(nearest(camps))):
            move_towards(unit_position(nearest(camps)))
            end_turn()
    if exists(goal) and distance(position(), goal) > 2 and fuel_remaining() > 55000:
        if ability_ready(0) and slot_is_dash(0):
            dash_towards(0, goal)
        if ability_ready(1) and slot_is_dash(1):
            dash_towards(1, goal)
    if exists(goal):
        claim(goal)
    move_towards(goal)
    if exists(first(filter(camps, in_attack_range()))):
        attack(first(filter(camps, in_attack_range())))
    end_turn()

