# PLAN (items and stats axis, unchanged from v1):
# 1. Casters (Marcella, Prism, Cassi, Willow) keep stacking Focus, since ability damage scales with it.
# 2. Melee carries and bruisers (Vesper Vale, Heart of Ruin, Vendetta, Tavi, Ryth) stack Power strength through the Power family emblem path (shard_of(family_power(), stat_strength())) so 5 identical shards make a strength emblem.
# 3. Tanks (Ren, Varg) keep stacking Health, and the Jungle/Treasure shard split is unchanged.
# 4. Everything else (abilities, camps, tribute, claims, fights) is the same as v1.
#
# COMBAT CHANGE (regroup before the first hit): a lone champion does not dive into a visible enemy
# champion. If enemies are within 6, no ally is within 3, and the nearest ally is within 8, step toward
# that ally first. Fights start 2v1 instead of 1v1, which is how the top teams win them.

# ability choice vs one target: damage or stun slots only, respecting range and type
def cast_on(slot, u):
    if ability_ready(slot) and not slot_is_dash(slot) and not slot_is_heal(slot) and not slot_is_reset(slot):
        if slot_is_shield(slot):
            if distance(position(), unit_position(u)) <= 3:
                cast_self(slot)
        elif distance(position(), unit_position(u)) <= slot_range(slot):
            if slot_is_aoe(slot):
                cast_at_tile(slot, unit_position(u))
            else:
                cast_at_unit(slot, u)

# ability choice vs one enemy: stun slot first (open with cc), else the other offensive slot
def cast_foe(u):
    if ability_ready(0) and slot_stun(0) > 0 and not slot_is_dash(0) and not slot_is_shield(0) and not slot_is_heal(0) and not slot_is_reset(0) and distance(position(), unit_position(u)) <= slot_range(0):
        if slot_is_aoe(0):
            cast_at_tile(0, unit_position(u))
        else:
            cast_at_unit(0, u)
    elif ability_ready(1) and not slot_is_dash(1) and not slot_is_shield(1) and not slot_is_heal(1) and not slot_is_reset(1) and distance(position(), unit_position(u)) <= slot_range(1):
        if slot_is_aoe(1):
            cast_at_tile(1, unit_position(u))
        else:
            cast_at_unit(1, u)
    elif ability_ready(0) and not slot_is_dash(0) and not slot_is_shield(0) and not slot_is_heal(0) and not slot_is_reset(0) and distance(position(), unit_position(u)) <= slot_range(0):
        if slot_is_aoe(0):
            cast_at_tile(0, unit_position(u))
        else:
            cast_at_unit(0, u)

def dash_to(slot, t):
    if ability_ready(slot):
        if slot_is_dash(slot):
            dash_towards(slot, t)

# ---- draft ----
if is_draft():
    let pool = unpicked_champions()
    if available(pool, champ_vendetta()):
