    end_turn()
if not at_spawn and gems() > 0 and health() < 0.5 * max_health() and not (in_danger() or enemies_within(8) > 0):
    recall()
    end_turn()

# CAST-AHEAD: open with an ability on a close enemy champion before it reaches us; the nearest
# enemy becomes the team target so allies converge on it (shared focus).
# Shield-first: with a foe within 3, a ready shield slot is raised before the offensive opener.
if exists( nf ):
    if distance(position(), unit_position(nf)) <= 4 and not contains( spawn_region(enemy()), unit_position(nf) ):
        set_team_target(nf)
        if ability_ready(1) and slot_radius(1) >= 2 and slot_is_aoe(1) and not slot_is_dash(1) and not slot_is_shield(1) and not slot_is_heal(1) and not slot_is_reset(1) and distance(position(), unit_position(nf)) <= slot_range(1) and enemies_within(slot_radius(1)) >= 2:
            cast_at_tile(1, unit_position(nf))
        elif ability_ready(0) and slot_is_shield(0) and distance(position(), unit_position(nf)) <= 3:
            cast_self(0)
        elif ability_ready(1) and slot_is_shield(1) and distance(position(), unit_position(nf)) <= 3:
            cast_self(1)
        else:
            cast_foe(nf)

# HEAL ALLY: heal slots go to the weakest hurt visible ally in range (never to an enemy, never wasted on self)
if (ability_ready(0) and slot_is_heal(0)) or (ability_ready(1) and slot_is_heal(1)):
