# Plan (vision v1: wards as the vision axis, abilities v3 kept):
# 1. Every turn, drop a free ward on an altar within 2 tiles (ward recharges over ~10 turns).
# 2. When enemies are near and no altar is in reach, ward a bush within 2 tiles to hide and deny sight lines.
# 3. Keep stun-then-burst casting. Attack reset (slot_is_reset) is self-cast after each basic attack, then we attack again.
# 4. Support, banking, and camp routing are unchanged from v0.

def cast_on(slot, u):
    if ability_ready(slot):
        if slot_is_heal(slot):
            if exists(weakest(allies_visible())) and unit_health_frac(weakest(allies_visible())) < 0.6:
                cast_at_unit(slot, weakest(allies_visible()))
            elif health() < 0.75 * max_health():
                cast_self(slot)
        elif slot_is_shield(slot):
            if health() < 0.85 * max_health() or enemies_within(4) > 0:
                cast_self(slot)
        elif slot_is_reset(slot):
            pass
        elif slot_is_dash(slot):
            pass
        elif distance(position(), unit_position(u)) <= slot_range(slot) + slot_radius(slot) + 1:
            if slot_is_aoe(slot) and slot_radius(slot) > 0:
                cast_at_tile(slot, unit_position(u))
            else:
                cast_at_unit(slot, u)

def dash_to(slot, t):
    if ability_ready(slot):
        if slot_is_dash(slot):
            dash_towards(slot, t)

# farm toward a chosen camp (no lets inside: it is expanded twice)
