            teleport_to(home)
            end_turn()
        if fuel_remaining() > 60000:
            dash_to(0, home)
            dash_to(1, home)
        move_towards(home)
        end_turn()
    recall()
    end_turn()
if not at_spawn and gems() > 0 and health() < 0.5 * max_health() and not (in_danger() or enemies_within(8) > 0):
    recall()
    end_turn()

# CAST-AHEAD
if exists( first(foes) ):
    let near_foe = nearest( foes )
    if exists(near_foe) and distance(position(), unit_position(near_foe)) <= 4 and not contains( spawn_region(enemy()), unit_position(near_foe) ):
        set_team_target(near_foe)
        if slot_is_dash(0) and slot_stun(0) > 0 and distance(position(), unit_position(near_foe)) >= 2 and fuel_remaining() > 60000:
            dash_to(0, unit_position(near_foe))
        if ability_ready(1) and slot_radius(1) >= 2 and slot_is_aoe(1) and not slot_is_dash(1) and not slot_is_shield(1) and not slot_is_heal(1) and not slot_is_reset(1) and distance(position(), unit_position(near_foe)) <= slot_range(1) and enemies_within(slot_radius(1)) >= 2:
            cast_at_tile(1, unit_position(near_foe))
        else:
            cast_foe(near_foe)

# HEAL ALLY
if (ability_ready(0) and slot_is_heal(0)) or (ability_ready(1) and slot_is_heal(1)):
    let hurt = weakest( allies_visible() )
    if exists(hurt) and unit_health_frac(hurt) < 0.6:
        if ability_ready(0) and slot_is_heal(0) and distance(position(), unit_position(hurt)) <= slot_range(0):
            cast_at_unit(0, hurt)
        elif ability_ready(1) and slot_is_heal(1) and distance(position(), unit_position(hurt)) <= slot_range(1):
            cast_at_unit(1, hurt)

# focus fire
let enemy = weakest( filter( foes, in_attack_range() ) )
if exists(enemy) and not contains( spawn_region(enemy()), unit_position(enemy) ):
    if health() < 0.5 * max_health():
        if ability_ready(0) and slot_is_shield(0):
            cast_self(0)
        elif ability_ready(1) and slot_is_shield(1):
            cast_self(1)
    if ability_ready(1) and slot_is_aoe(1) and slot_radius(1) >= 2 and enemies_within(slot_radius(1)) >= 2 and not slot_is_dash(1) and not slot_is_shield(1) and not slot_is_heal(1) and not slot_is_reset(1):
        cast_at_tile(1, unit_position(enemy))
    cast_on(0, enemy)
    cast_on(1, enemy)
    attack(enemy)
    if ability_ready(0) and slot_is_reset(0):
        cast_self(0)
    if ability_ready(1) and slot_is_reset(1):
        cast_self(1)
    attack(enemy)
    end_turn()

# outnumbered: duck into a nearby bush (breaks their vision), else step away
let nf = nearest( foes )
if exists(nf) and distance(position(), unit_position(nf)) <= 5 and local_strength(6) < 0.8 and not contains( spawn_region(enemy()), unit_position(nf) ):
    let hide = closest( filter( bushes(), within(2, position()) ) )
    if exists(hide) and distance(unit_position(nf), hide) >= 3 and not contains(bushes(), position()):
        move_towards(hide)
        end_turn()
    move_away_from( unit_position(nf) )
    end_turn()

# tribute only with a worthwhile bag
let bag_ready = gems() >= 25 or round_number() > 1500 or health() < 0.3 * max_health()
if gems() > 0 and bag_ready:
    let altar = first( filter( altars(), within(1, position()) ) )
    if exists(altar):
        tribute(altar)
        end_turn()
    let target = closest( minus( safe_altar_ring, ring(locked_altars(), 1) ) )
    if exists(target):
        if has_teleport() and distance(position(), target) >= 2 and distance(position(), target) <= 3:
            teleport_to(target)
            end_turn()
        move_towards(target)
        end_turn()
    let target2 = closest(safe_altar_ring)
    if exists(target2):
        move_towards(target2)
        end_turn()
    let altar_goal = closest(altar_ring)
    if contains(camp_spawns, altar_goal):
        let blocker = first( filter( camps_visible(), in_attack_range() ) )
        if exists(blocker):
            attack(blocker)
            end_turn()
    move_towards( altar_goal )
    end_turn()

let camps = camps_visible()

let camp = first( filter( camps, in_attack_range() ) )
if exists(camp):
    if ability_ready(1) and slot_is_aoe(1) and slot_radius(1) >= 2 and not slot_is_dash(1) and not slot_is_shield(1) and not slot_is_heal(1) and not slot_is_reset(1):
        cast_at_tile(1, unit_position(camp))
    cast_on(0, camp)
    cast_on(1, camp)
    attack(camp)
    if ability_ready(0) and slot_is_reset(0):
        cast_self(0)
    if ability_ready(1) and slot_is_reset(1):
        cast_self(1)
    attack(camp)
    end_turn()

if team_score(ally()) == 0 and round_number() > 800:
    move_towards( closest( minus( minus( camp_spawns, respawning_visible_spawns() ), golem_tiles() ) ) )
    end_turn()
let goals = minus( minus( minus( minus( camp_spawns, respawning_visible_spawns() ), monolith_tiles() ), golem_tiles() ), mono_groups )

if contains(capturable_spawns(), position()):
    end_turn()

let free_goals = minus( goals, claimed_by_allies() )
let goal = closest( free_goals )
if not exists(goal):
    move_towards( closest(goals) )
    end_turn()
claim(goal)

# MACRO: bank before committing to a mid/high-threat group (was 240), so the bag is safe during the clear
if exists(goal) and gems() >= 10 and group_threat(goal) >= 120 and fuel_remaining() > 65000:
    let bank_altar = first( filter( altars(), within(1, position()) ) )
    if exists(bank_altar):
        tribute(bank_altar)
        end_turn()
    move_towards( closest(safe_altar_ring) )
    end_turn()
if distance(goal, position()) == 0:
    let live = nearest(camps)
    if exists(live) and not contains( union( monolith_tiles(), golem_tiles() ), unit_position(live) ):
        move_towards( unit_position(live) )
        end_turn()
if exists(goal) and distance(position(), goal) > 2 and fuel_remaining() > 65000:
    dash_to(0, goal)
    dash_to(1, goal)
move_towards( goal )
let camp2 = first( filter( camps, in_attack_range() ) )
if exists(camp2):
    attack(camp2)
set_priority( 1 + random_int(100) )
end_turn()
